import math

import backtrader as bt


class AAPLStochasticRiskStrategy(bt.Strategy):
    params = (('risk_per_trade', 0.01),)

    def __init__(self):
        stochastic = bt.indicators.StochasticFull(
            self.data,
            period=14,
            period_dfast=3,
            period_dslow=3,
        )
        self.k = stochastic.percK
        self.d = stochastic.percD
        self.atr = bt.indicators.ATR(self.data, period=14)

        self.entry_order = None
        self.close_order = None
        self.stop_order = None
        self.pending_reverse = None

    def _size_for_entry(self, entry_price):
        stop_price = entry_price * (0.98 if self.pending_reverse != 'short' else 1.02)
        stop_distance_dollars = abs(entry_price - stop_price)
        return math.floor(
            (self.broker.getvalue() * self.p.risk_per_trade)
            / stop_distance_dollars
        )

    def _submit_entry(self, direction):
        self.pending_reverse = direction
        entry_price = self.data.close[0]
        size = self._size_for_entry(entry_price)
        if size <= 0:
            self.pending_reverse = None
            return
        if direction == 'long':
            self.entry_order = self.buy(size=size)
        else:
            self.entry_order = self.sell(size=size)
        self.pending_reverse = None

    def _submit_close(self):
        if self.stop_order is not None:
            self.cancel(self.stop_order)
        self.close_order = self.close()

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        if order is self.entry_order:
            if order.status == order.Completed:
                entry_price = order.executed.price
                if order.isbuy():
                    stop_price = entry_price * 0.98
                    self.stop_order = self.sell(
                        size=order.executed.size,
                        exectype=bt.Order.Stop,
                        price=stop_price,
                    )
                else:
                    stop_price = entry_price * 1.02
                    self.stop_order = self.buy(
                        size=abs(order.executed.size),
                        exectype=bt.Order.Stop,
                        price=stop_price,
                    )
            self.entry_order = None
        elif order is self.close_order:
            self.close_order = None
        elif order is self.stop_order:
            self.stop_order = None

    def next(self):
        if self.entry_order is not None or self.close_order is not None:
            return

        bullish_entry = (
            self.k[-1] < 20
            and self.k[-1] <= self.d[-1]
            and self.k[0] > self.d[0]
        )
        bearish_entry = (
            self.k[-1] > 80
            and self.k[-1] >= self.d[-1]
            and self.k[0] < self.d[0]
        )

        if not self.position:
            if self.pending_reverse is not None:
                direction = self.pending_reverse
                self._submit_entry(direction)
            elif bullish_entry:
                self._submit_entry('long')
            elif bearish_entry:
                self._submit_entry('short')
            return

        if self.position.size > 0:
            if bearish_entry:
                self.pending_reverse = 'short'
                self._submit_close()
            elif self.k[-1] >= 50 and self.k[0] < 50:
                self._submit_close()
        else:
            if bullish_entry:
                self.pending_reverse = 'long'
                self._submit_close()
            elif self.k[-1] <= 50 and self.k[0] > 50:
                self._submit_close()
